package com.codepilot1c.core.tools.development;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.codepilot1c.core.edt.development.*;
import com.codepilot1c.core.tools.*;
import com.codepilot1c.core.tools.workspace.BackgroundJobRegistry;
@ToolMeta(name="edt_runtime_host",category="qa",mutating=true,tags={"workspace","edt","sensitive"})
public final class EdtRuntimeHostTool extends AbstractTool {
    private static final Gson RESULT_JSON=new GsonBuilder().serializeNulls().create();
    @Override public String getDescription(){return "Native API BSL host without VAExtension. prepare mode=external creates an owned EDT external EPF project. mode=metadata creates only an internal temporary DataProcessor; no external project or EPF. Requires associated permitted test base. Omit both native_path/expected_native_sha256 to use the pinned, automatically downloaded and SHA256-verified bundled Native package; explicit custom path/hash remains supported. package_status/prepare_package/configure_package manage only the shared package cache without a host_id, launching 1C, updating DB or changing trust; automatic_download defaults true. First metadata start FULL-updates the whole project into the base; an unchanged previously loaded host with current native EQUAL skips updating. external mode never updates it. Own Enterprise client loads EPF/native component; platform trust may require local preparation. execute returns request_id; poll result. context client/server; execution_mode info/execute/query/external; parameters becomes ПараметрыВызова, assign Результат. Claims never automatically replay. stop affects only owned client. cleanup checks ownership/source hashes, native-deletes metadata, FULL-updates base and independently proves absence by a generation-checked CF/XML snapshot compared with DBConfiguration using native Designer. Legacy hosts retain EPF verification. cleanup_external_project removes only the owned external project/files, without FULL update or claiming database absence; verifier EPF is preserved for pending metadata cleanup. cleanup may reuse verification_host_id: an already running native host on the exact same synchronized base, without FULL or a new verifier client. Edited sources are preserved. No business data rollback. prepare/start/cleanup return job_id; poll edt_operation_status. Artifacts stay in workspace metadata. execution_mode=batch accepts up to 16 explicit steps with code/context/parameters/caption/screenshot; runs in 1C over timer ticks, yields to paint before each capture, stops on the first failure and returns completed step results. No automatic replay after unknown outcome. Client BSL can call КомпонентаАгента.Screenshot() and parse its JSON manifest, collecting images inside one batch. action=snapshots returns verified paths/hashes associated with request_id (optional request_id filters one batch); images stay in owned host storage until cleanup, no base64 JSON. With action=snapshots, grid=true adds an alignment.image_path PNG with rulers and grid_step(default20px,8..500); image_path/sha256 remain original. Annotation does not recapture or execute 1C. Partial annotation returns original images with alignment_error and alignment_all_succeeded=false; never replay BSL for this. Coordinates are original-image pixels, origin32px in annotated PNG. Batch kind=wait repeats explicitly side-effect-free BSL returning Boolean until true, timeout_ms default60000 (1000..300000), interval_ms default1000 (1000..10000); this budget cannot preempt synchronous BSL/RPC. kind=assert evaluates Boolean once; false or non-Boolean stops dependent steps. kind=read executes caller-supplied read-only BSL and select projects up to32 dot paths from its JSON value (array indexes zero-based); it is not automatic discovery of arbitrary open forms. screenshot_on_failure captures on the next timer tick before stopping. result includes durable progress: phase, sequence, append-only step receipts, also after disconnect; progress is not terminal success. Completed values above16384 JSON characters are explicitly omitted; use a narrow read, never replay mutations. New controls require host_features batch_controls_v1; old hosts retain plain batches. Native binary/protocol unchanged. execute/result default to compact original-receipt views; details or compact=false preserves full values/errors/nulls. Small non-batch successful values up to1024 UTF8 JSON bytes are inlined as value/value_inlined; larger values set value_in_details, avoiding a details call for simple scalar reads. wait timeout_ms0..25000 waits for semantic progress/completion without resubmitting. cursor/page_size1..16 return only new step summaries/capture receipts. Cursors bind host/request/acknowledged prefixes, survive restart and fail explicitly after incompatible changes/cleanup. Waiting attempts/elapsed alone are not new events. next_call always observes the original request; failed/unknown routes to details, never new execution. Capture receipts omit image paths; artifacts_call uses unchanged snapshots verification to obtain trusted paths/grid. Host status/execute compare local required Native release/hash/protocol and actual owned archive/template without network. ensure_current prepares the pinned shared package if needed, returns unchanged when current, never replaces a live host. refresh_preview returns a hash-bound owned-host replacement plan; refresh requires expected_plan_sha256 and, for metadata only, allow_database_update=true because cleanup/start FULL-update the entire project. Active/unknown requests and edited resources block replacement. Durable refresh_status retains original old/new IDs after failures/restart; retries never resume/replay the replacement automatically. Explicit custom verified packages remain supported and are not silently replaced. Native component Windows x64 only.";}
    @Override public String getParameterSchema(){return """
        {"type":"object","additionalProperties":false,"required":["action"],"properties":{
          "action":{"type":"string","enum":["prepare","start","status","execute","result","wait","details","ensure_current","refresh_preview","refresh","refresh_status","stop","cleanup","cleanup_external_project","snapshots","package_status","prepare_package","configure_package"]},
          "project":{"type":"string"},"mode":{"type":"string","enum":["external","metadata"]},
          "native_path":{"type":"string"},"expected_native_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},
          "allow_database_update":{"type":"boolean","default":false},"expected_plan_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},
          "compact":{"type":"boolean","default":true},"cursor":{"type":"string","maxLength":8192},"page_size":{"type":"integer","minimum":1,"maximum":16,"default":8},"timeout_ms":{"type":"integer","minimum":0,"maximum":25000,"default":20000},
          "automatic_download":{"type":"boolean"},"host_id":{"type":"string"},"verification_host_id":{"type":"string"},"request_id":{"type":"string"},"idempotency_key":{"type":"string"},
          "execution_mode":{"type":"string","enum":["info","execute","query","external","batch"],"default":"execute"},
          "context":{"type":"string","enum":["server","client"],"default":"server"},
          "code":{"type":"string","maxLength":131072},"query":{"type":"string","maxLength":131072},
          "steps":{"type":"array","minItems":1,"maxItems":16,"items":{"type":"object","additionalProperties":false,"required":["code"],"properties":{"code":{"type":"string","maxLength":8192},"context":{"type":"string","enum":["client","server"],"default":"client"},"parameters":{"type":"object"},"caption":{"type":"string","maxLength":200},"screenshot":{"type":"boolean","default":false},"kind":{"type":"string","enum":["execute","wait","assert","read"],"default":"execute"},"timeout_ms":{"type":"integer","minimum":1000,"maximum":300000,"default":60000},"interval_ms":{"type":"integer","minimum":1000,"maximum":10000,"default":1000},"select":{"type":"array","maxItems":32,"uniqueItems":true,"items":{"type":"string","maxLength":200}},"screenshot_on_failure":{"type":"boolean","default":false}}}},
          "grid":{"type":"boolean","default":false},"grid_step":{"type":"integer","minimum":8,"maximum":500,"default":20},
          "parameters":{"type":"object"},"limit":{"type":"integer","minimum":1,"maximum":1000,"default":100},
          "artifact_path":{"type":"string"},"expected_artifact_sha256":{"type":"string"},"method":{"type":"string"}
        }}
        """;}
    @Override protected CompletableFuture<ToolResult> doExecute(ToolParameters p){return CompletableFuture.supplyAsync(()->{try{
        Map<String,Object> a=p.getRaw();String action=RuntimeExecutionPlan.required(a,"action");
        if(Set.of("package_status","prepare_package","configure_package").contains(action)){
            if(!(action.equals("configure_package")?Set.of("action","automatic_download"):Set.of("action")).containsAll(a.keySet()))throw new IllegalArgumentException("Field does not apply to Native package action");var packages=NativePackageManager.getInstance();Object answer;
            if(action.equals("configure_package")){if(!(a.get("automatic_download") instanceof Boolean enabled))throw new IllegalArgumentException("automatic_download must be boolean");answer=packages.configure(enabled);}else answer=action.equals("package_status")?packages.status():packages.prepare();
            return ToolResult.success(RESULT_JSON.toJson(answer));
        }
        if(a.containsKey("allow_database_update")&&!(a.get("allow_database_update") instanceof Boolean))throw new IllegalArgumentException("allow_database_update must be boolean");
        if((a.containsKey("allow_database_update")||a.containsKey("expected_plan_sha256"))&&!action.equals("refresh"))throw new IllegalArgumentException("Refresh fields require action=refresh");
        for(String key:List.of("compact","cursor","page_size","timeout_ms"))if(a.containsKey(key)&&!Set.of("execute","result","wait").contains(action))throw new IllegalArgumentException(key+" only applies to execute/result/wait");
        NativeHostService.validateViewArguments(a);
        if(action.equals("execute")&&(a.containsKey("cursor")||a.containsKey("timeout_ms")))throw new IllegalArgumentException("execute does not accept cursor/timeout_ms");
        if(a.containsKey("grid")||a.containsKey("grid_step")){com.codepilot1c.core.edt.editor.SnapshotAlignment.options(a);if(!action.equals("snapshots"))throw new IllegalArgumentException("grid/grid_step require action=snapshots");}NativeHostService service=new NativeHostService();
        if(Set.of("prepare","start","cleanup","cleanup_external_project","ensure_current","refresh").contains(action)){
            String id=action.equals("prepare")?null:RuntimeExecutionPlan.required(a,"host_id");
            String job=BackgroundJobRegistry.getInstance().startJob("native-host-"+action,()->RESULT_JSON.toJson(switch(action){case "prepare"->service.prepare(a);case "start"->service.start(id);case "ensure_current"->service.ensureCurrent(id);case "refresh"->service.refresh(id,RuntimeExecutionPlan.required(a,"expected_plan_sha256"),Boolean.TRUE.equals(a.get("allow_database_update")));case "cleanup_external_project"->service.cleanupExternal(id);default->service.cleanup(id,(String)a.get("verification_host_id"));}));
            return ToolResult.success(RESULT_JSON.toJson(Map.of("job_id",job,"next_tool","edt_operation_status")));
        }
        String id=RuntimeExecutionPlan.required(a,"host_id");Map<String,Object> result=switch(action){
        case "refresh_preview"->service.refreshPreview(id);case "refresh_status"->service.refreshStatus(id);case "snapshots"->service.snapshots(id,(String)a.get("request_id"),a);case "status"->service.status(id);case "execute"->{var submitted=service.execute(id,a);yield Boolean.FALSE.equals(a.get("compact"))?submitted:service.observe(id,submitted.get("request_id").toString(),a,false);}case "result","wait"->service.observe(id,RuntimeExecutionPlan.required(a,"request_id"),a,action.equals("wait"));case "details"->service.result(id,RuntimeExecutionPlan.required(a,"request_id"));case "stop"->service.stop(id);default->throw new IllegalArgumentException("Unknown action");};
        return ToolResult.success(RESULT_JSON.toJson(result));
    }catch(NativeHostService.CompatibilityRequired e){return ToolResult.success(RESULT_JSON.toJson(e.result()));}catch(Exception e){return ToolResult.failure("edt_runtime_host: "+e.getMessage());}});}
}
